    use super::*;

    struct Case {
        name: &'static str,
        input: Order,
        expected: Result<(), OrderError>,
    }

    #[test]
    fn validate_order_cases() {
        let cases = vec![
            Case {
                name: "valid order",
                input: Order { id: 1, items: vec![item(1)], total: 100 },
                expected: Ok(()),
            },
            Case {
                name: "empty items",
                input: Order { id: 2, items: vec![], total: 100 },
                expected: Err(OrderError::NoItems),
            },
            Case {
                name: "zero total",
                input: Order { id: 3, items: vec![item(1)], total: 0 },
                expected: Err(OrderError::InvalidTotal { total: 0 }),
            },
            Case {
                name: "negative total",
                input: Order { id: 4, items: vec![item(1)], total: -5 },
                expected: Err(OrderError::InvalidTotal { total: -5 }),
            },
        ];

        for case in cases {
            assert_eq!(
                validate_order(&case.input),
                case.expected,
                "case: {}",
                case.name,
            );
        }
    }
}
```

This requires `OrderError: PartialEq` (usually derivable). The `"case: {}"` message is what makes a table test debuggable — without it, a failure only tells you the position in the `Vec`.

**On checking error cases specifically:** assert the *specific* variant, not just that it errored. `assert!(result.is_err())` passes for `NoItems` when you expected `InvalidTotal`, so it hides regressions. Two ways to pin the variant:

- `assert_eq!` against the full `Err(OrderError::InvalidTotal { total: 0 })` when the error derives `PartialEq` and you want to check the payload too.
- `matches!` when the error isn't `PartialEq`, or you only care about the variant, not every field:

```rust
let err = validate_order(&order).unwrap_err();
assert!(
    matches!(err, OrderError::InvalidTotal { .. }),
    "expected InvalidTotal, got {err:?}",
);
```

If the error has fields with values you care about, match and destructure:

```rust
let err = validate_order(&order).unwrap_err();
match err {
    OrderError::InvalidTotal { total } => assert_eq!(total, -5),
    other => panic!("expected InvalidTotal, got {other:?}"),
}
```

