Declare a small local case struct, then iterate a `Vec` of cases inside one `#[test]`:

```rust
#[cfg(test)]
mod tests {
    use super::*;

    struct Case {
        name: &'static str,
        input: Order,
        expected: Result<(), OrderError>,
    }

    #[test]
    fn validates_order_cases() {
        let cases = vec![
            Case { name: "happy path", input: valid_order(), expected: Ok(()) },
            Case {
